// Scan only current/late-changing native WhatsApp campaigns. No manual IDs.
const raw=$input.all().map(x=>x.json).filter(x=>x&&Object.keys(x).length);
if(raw.some(x=>x.error))return [{json:{hasCampaign:false,reason:'CHATWOOT_CAMPAIGN_LIST_UNAVAILABLE',availability:'BLOCKED'}}];
const now=Date.now(),windowDays=14,scanBatchSize=5,scanPeriodHours=6;
const earliest=now-windowDays*86400000;
const all=[];
for(const c of raw){
  if(c.campaign_type!=='one_off'||c.inbox?.channel_type!=='Channel::Whatsapp')continue;
  if(!['completed','processing'].includes(c.campaign_status))continue;
  const stamp=Number(c.completed_at||c.started_at||0);
  if(c.campaign_status==='completed' && stamp>0 && stamp*1000<earliest)continue;
  const id=Number(c.id);
  if(!Number.isSafeInteger(id)||id<1)throw new Error('Invalid WhatsApp campaign display ID');
  all.push({id,title:String(c.title||'').slice(0,90),status:c.campaign_status,completedAt:c.completed_at??null,stamp});
}
all.sort((a,b)=>b.stamp-a.stamp||b.id-a.id);
const groups=Math.ceil(all.length/scanBatchSize);
if(groups===0)return [{json:{hasCampaign:false,reason:'NO_RECENT_NATIVE_WHATSAPP_CAMPAIGNS',availability:'NO_DATA'}}];
// Rotate in 6h windows. Cap API load while making EVERY group reachable eventually.
const slot=Math.floor(now/(scanPeriodHours*3600000)),group=slot%groups;
const selected=all.slice(group*scanBatchSize,(group+1)*scanBatchSize);
return selected.map(c=>({json:{
 hasCampaign:true,campaignId:c.id,title:c.title,status:c.status,completedAt:c.completedAt,
 totalEligible:all.length,selectedCount:selected.length,scanGroup:group,scanGroups:groups,
 readOnly:true
}}));

// Metrics output loses its campaign ID; recover it from the COMMUNITY NODE'S input pairing.
// Preserve 1:1 item pairing into failed-recipient lookup.
const selected=$('Select Recent Campaigns - Rotating Batches').all().map(x=>x.json).filter(x=>x.hasCampaign);
const items=$input.all(),seen=new Set(),out=[];
for(const x of items){
 const p=Array.isArray(x.pairedItem)?x.pairedItem[0]:x.pairedItem;
 if(!p||!Number.isInteger(p.item)||p.item<0||p.item>=selected.length)throw new Error('METRICS_INPUT_PAIRING_MISSING');
 const i=p.item;if(seen.has(i))throw new Error('DUPLICATE_METRICS_PAIRING');seen.add(i);
 const m=x.json||{};
 if(m.error||!Number.isSafeInteger(m.audience)){
   out.push({json:{...selected[i],metricsAvailable:false,blockedReason:'CAMPAIGN_ANALYTICS_NOT_AVAILABLE',
     failedExpected:null,counts:null},pairedItem:{item:i}});
   continue;
 }
 const keys=['audience','sent','delivered','read','failed','skipped'];
 if(keys.some(k=>!Number.isSafeInteger(m[k])||m[k]<0))throw new Error('INVALID_ANALYTICS_COUNTERS');
 if(m.read>m.delivered||m.delivered>m.audience||m.failed>m.audience)throw new Error('CONTRADICTORY_ANALYTICS_COUNTERS');
 out.push({json:{...selected[i],metricsAvailable:true,failedExpected:m.failed,
   counts:{audience:m.audience,sent:m.sent,deliveredIncludingRead:m.delivered,read:m.read,failed:m.failed,skipped:m.skipped}},
   pairedItem:{item:i}});
}
if(seen.size!==selected.length)throw new Error('INCOMPLETE_METRICS_RESPONSES');
return out;

// Failed-recipient API is filtered at source. Verify failure count and do not expose PII.
const metadata=$('Attach Campaign Context to Metrics').all().map(x=>x.json);
const failed=new Map(),blocked=new Set();
const list=$input.all();
for(const item of list){
 const raw=item.json||{};
 // n8n may emit one *unpaired* empty item if the entire failed-only query has no matches.
 if(Object.keys(raw).length===0 && !item.pairedItem)continue;
 const p=Array.isArray(item.pairedItem)?item.pairedItem[0]:item.pairedItem;
 if(!p||!Number.isInteger(p.item)||p.item<0||p.item>=metadata.length)
   throw new Error('RECIPIENT_CAMPAIGN_PAIRING_MISSING');
 const idx=p.item;
 if(!failed.has(idx))failed.set(idx,[]);
 if(raw.error){blocked.add(idx);continue;}
 if(Object.keys(raw).length===0)continue; // zero failed recipients for this campaign
 if(raw.status!=='failed')throw new Error('UNFILTERED_RECIPIENT_RESPONSE');
 const id=Number(raw.contact?.id);
 if(!Number.isSafeInteger(id)||id<1)throw new Error('MISSING_CONTACT_ID');
 failed.get(idx).push({id,code:raw.error_code==null?'UNKNOWN':String(raw.error_code)});
}
const reports=[];
for(let idx=0;idx<metadata.length;idx++){
 const c=metadata[idx],rows=failed.get(idx)||[],seen=new Set(),codes={};
 if(c.metricsAvailable){
   for(const r of rows){
     if(seen.has(r.id))throw new Error('DUPLICATE_FAILED_CONTACT');
     seen.add(r.id);
     if(!/^(UNKNOWN|[0-9]{3,8})$/.test(r.code))throw new Error('INVALID_META_ERROR_CODE');
     codes[r.code]=(codes[r.code]||0)+1;
   }
 }
 let status='PASS',reason=null;
 if(!c.metricsAvailable){status='BLOCKED';reason=c.blockedReason;}
 else if(blocked.has(idx)){status='BLOCKED';reason='RECIPIENT_ANALYTICS_NOT_AVAILABLE';}
 else if(rows.length!==c.failedExpected){status='BLOCKED';reason='FAILED_RECIPIENT_COUNT_MISMATCH';}
 reports.push({chatwootCampaignId:c.campaignId,title:c.title,campaignStatus:c.status,
   status,reason,counts:c.counts,errorCodeCounts:status==='PASS'?codes:null,
   verifiedCrmMapping:false,crmEventWriteAuthorized:false});
}
return [{json:{checkedAt:new Date().toISOString(),mode:'READ_ONLY',
 status:reports.some(r=>r.status==='BLOCKED')?'PARTIAL_OR_BLOCKED':'PASS',
 scan:{selected:metadata.length,eligible:metadata[0]?.totalEligible||0,group:metadata[0]?.scanGroup||0,groups:metadata[0]?.scanGroups||0},
 reports,crmEventWriteAuthorized:false,sendAttempted:false,
 note:'Chatwoot provider IDs/times and EspoCRM batch mappings are not available from this analytics API.'}}];
